bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true || exit 60
docker exec -i -w /opt/videobot "$cid" node --input-type=module <<'JS'
import pg from 'pg';import {readFileSync} from 'node:fs';
import {setDefaultResultOrder} from 'node:dns';import {setDefaultAutoSelectFamily} from 'node:net';
import {createCreatorTelegramFetch} from '/opt/videobot/src/runtime/creatorEgress.mjs';
setDefaultResultOrder('ipv4first');setDefaultAutoSelectFamily(false);
const outbound=createCreatorTelegramFetch();
const e=process.env,token=readFileSync('/run/secrets/videobot_telegram_token','utf8').trim();
const db=new pg.Pool({host:e.VIDEOBOT_DB_HOST,user:e.VIDEOBOT_DB_USER,database:e.VIDEOBOT_DB_NAME,password:readFileSync('/run/secrets/videobot_db_password','utf8').trim(),max:1,connectionTimeoutMillis:5000});
let done=0;
try{
 const q=await db.query("SELECT l.thumbnail_file_id,l.sample_file_id,l.paid_video_file_id,l.sample_duration_seconds,a.free_message_ids,a.paid_message_id,a.topic_id FROM videobot_post_receipts a JOIN videobot_listings l ON l.listing_id=a.listing_id WHERE a.paid_message_id=4691 AND a.free_message_ids=ARRAY[4689,4690]::bigint[] AND a.status='sent'");
 if(q.rowCount!==1)throw Object.assign(Error('RECEIPT_NOT_EXACT'),{code:61});
 const r=q.rows[0];const ids=r.free_message_ids.map(Number);
 if(ids[0]!==4689||ids[1]!==4690||Number(r.paid_message_id)!==4691||!r.thumbnail_file_id||!r.sample_file_id||r.sample_file_id===r.paid_video_file_id||!(Number(r.sample_duration_seconds)>0&&Number(r.sample_duration_seconds)<=30))throw Object.assign(Error('MEDIA_NOT_VERIFIED'),{code:62});
 for(let i=0;i<2;i++){
  const payload={chat_id:-1002373696859,message_id:ids[i],media:{type:i===0?'photo':'video',media:i===0?r.thumbnail_file_id:r.sample_file_id,has_spoiler:true}};
  const response=await outbound.fetch((e.VIDEOBOT_LOCAL_API_URL??'https://api.telegram.org')+'/bot'+token+'/editMessageMedia',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload),signal:AbortSignal.timeout(30000)});
  const body=await response.json().catch(()=>null);
  if(body?.ok===true&&Number(body.result?.message_id)===ids[i]&&body.result?.has_media_spoiler===true){done++;continue}
  if(response.status===400&&String(body?.description).toLowerCase().includes('message is not modified')){done++;continue}
  throw Object.assign(Error('TELEGRAM_EDIT_REFUSED_'+i),{code:70+i});
 }
 console.log('OLD_TWO_FREE_POST_SPOILER_REPAIR_VERIFIED=PASS');
 console.log('OLD_PAID_POST_UNTOUCHED=PASS');
}catch(err){console.error('OLD_FREE_SPOILER_EDIT_FAILURE_STEP='+done);process.exitCode=Number(err.code)||79}
finally{await outbound.close();await db.end()}
JS
